<?php $quote = $order['quotes'][0] ?? null; ?>
<div class="cx-columns">
    <div class="cx-stack">
        <section class="cx-panel cx-freight-note"><p class="lp-eyebrow">CURRENT STATUS</p><h2><?php echo authEscape($order['status']); ?></h2><p class="cx-intro cx-note">Order <?php echo authEscape($order['id']); ?> &middot; Placed <?php echo authEscape($order['created_at']); ?> UTC</p></section>
        <section class="cx-panel"><h2>Ordered pallets</h2><?php foreach ($order['items'] as $item): ?><div class="cx-order-line"><div><?php echo authEscape($item['product_name']); ?><small><?php echo (int)$item['quantity']; ?> &times; <?php echo authEscape($item['pallet_type']); ?> &middot; <?php echo formatPrice((float)$item['unit_price']); ?> each</small></div><strong><?php echo formatPrice((float)$item['line_total']); ?></strong></div><?php endforeach; ?></section>
        <section class="cx-panel"><h2>Order history</h2><ol class="cx-timeline"><?php foreach ($order['events'] as $event): ?><li class="cx-timeline-complete"><span class="cx-timeline-marker" aria-hidden="true">&#10003;</span><div><h3><?php echo authEscape($event['status']); ?></h3><p><?php echo authEscape($event['created_at']); ?> UTC</p><?php if ($event['note']): ?><p><?php echo authEscape($event['note']); ?></p><?php endif; ?></div></li><?php endforeach; ?></ol></section>
    </div>
    <aside class="cx-stack">
        <section class="cx-panel"><h2>Delivery destination</h2><dl class="cx-facts"><div><dt>Business</dt><dd><?php echo authEscape($order['company']); ?></dd></div><div><dt>Contact</dt><dd><?php echo authEscape($order['customer_name']); ?></dd></div><div><dt>Email</dt><dd><?php echo authEscape($order['email']); ?></dd></div><div><dt>Address</dt><dd><?php echo authEscape($order['street']); ?><br><?php echo authEscape($order['city'] . ', ' . $order['state'] . ' ' . $order['zip']); ?></dd></div></dl></section>
        <section class="cx-panel cx-summary"><h2>Order totals</h2><dl class="cx-facts"><div><dt>Product subtotal</dt><dd><?php echo formatPrice((float)$order['subtotal']); ?></dd></div><div><dt>Freight</dt><dd><?php echo $quote ? formatPrice((float)$order['shipping']) : 'Pending quote'; ?></dd></div><div><dt>Estimated tax</dt><dd><?php echo formatPrice((float)$order['tax']); ?></dd></div></dl><div class="cx-total"><span><?php echo $quote ? 'Total' : 'Before freight'; ?></span><span><?php echo formatPrice((float)$order['total']); ?></span></div><p class="cx-note">No online payment is collected here. Contact our team to arrange payment.</p></section>
        <section class="cx-panel"><h2>Freight details</h2><?php if ($quote): ?><dl class="cx-facts"><div><dt>Carrier</dt><dd><?php echo authEscape($quote['carrier']); ?></dd></div><div><dt>Service</dt><dd><?php echo authEscape($quote['service']); ?></dd></div><div><dt>Rate</dt><dd><?php echo formatPrice((float)$quote['rate']); ?></dd></div></dl><?php else: ?><p class="cx-intro cx-note"><?php echo $order['status'] === 'Cancelled' ? 'This order was cancelled before freight was confirmed.' : 'Our team will review the destination and confirm your delivery rate.'; ?></p><?php endif; ?></section>
    </aside>
</div>
